function alternator(array, itemize, between) {
    const end_index = array.length - 1;
    const results = [];
    array.forEach((item, index) => {
        results.push(itemize(item, index));
        if (index !== end_index)
            results.push(between(item, index));
    });
    return results;
}

function sizing_styles(size) {
    return size !== null
        ? `flex: 0 0 ${size}%;`
        : `flex: 1 1 auto;`;
}

